/* Speakmi brand assets: logo and Lexend font (SIL Open Font License), embedded so no network or web-accessible resources are needed. */
(function (root) {
  const FONTS = { 400: "", 600: "", 800: "" };
  function bytes(b64) { const bin = atob(b64), out = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i); return out.buffer; }
  let loading = null;
  function loadFonts() {
    if (loading) return loading;
    try {
      loading = Promise.all(Object.keys(FONTS).map((w) => {
        const f = new FontFace("Speakmi Lexend", bytes(FONTS[w]), { weight: w });
        return f.load().then((x) => { document.fonts.add(x); });
      })).then(() => true).catch(() => false);
    } catch (e) { loading = Promise.resolve(false); }
    return loading;
  }
  root.SpeakmiBrand = { logo: "data:image/png;base64,", loadFonts };
})(typeof self !== "undefined" ? self : this);
